      semiBold12: defaultStyle.copyWith(fontSize: 12, fontWeight: FontWeight.w700),
      semiBold16: defaultStyle.copyWith(fontSize: 16, fontWeight: FontWeight.w700),
    );
  }

  const ThemeFonts.raw({
    required this.regular12,
    required this.regular14,
    required this.regular16,
    required this.semiBold12,
    required this.semiBold16,
  });

  final TextStyle regular12;
  final TextStyle regular14;
  final TextStyle regular16;
  final TextStyle semiBold12;
  final TextStyle semiBold16;

  @override
  ThemeFonts copyWith({
    final TextStyle? regular12,
    final TextStyle? regular14,
    final TextStyle? regular16,
    final TextStyle? semiBold12,
    final TextStyle? semiBold16,
